// PoC-SMF: minimal PGW/SMF-side responder for CreateSessionRequest on S5-C.
// Listens on UDP/2123, parses CSR from SGW-C, and returns a simple
// CreateSessionResponse so the MME-side PoC can complete.
func main() {
	laddr := flag.String("laddr", "0.0.0.0", "Local IP to bind for S5-C (use the IP SGW-C will send to)")
	port := flag.Int("port", 2123, "GTP-C port")
	paa := flag.String("paa", "10.60.0.10", "PDN Address Allocation to return")
	ebi := flag.Uint("ebi", 5, "Default bearer EBI to echo in BearerContextCreated")
	pgwCtrlTEID := flag.Uint("pgw-teid", 0, "PGW S5-C TEID to advertise (0=random non-zero)")
	pgwUTeid := flag.Uint("pgw-uteid", 0, "PGW S5-U TEID to advertise (0=random non-zero)")
	delay := flag.Duration("delay", 0, "Optional delay before sending CSR response (simulates slow SMF)")
	flag.Parse()

	rand.Seed(time.Now().UnixNano())

	addr, err := net.ResolveUDPAddr("udp", net.JoinHostPort(*laddr, fmt.Sprintf("%d", *port)))
	if err != nil {
		log.Fatalf("resolve laddr: %v", err)
	}
	conn, err := net.ListenUDP("udp", addr)
	if err != nil {
		log.Fatalf("listen udp: %v", err)
	}
	defer conn.Close()

	log.Printf("[*] PoC-SMF listening on %s (paa=%s ebi=%d)", addr, *paa, *ebi)

	buf := make([]byte, 4096)
	for {
		n, raddr, err := conn.ReadFromUDP(buf)
		if err != nil {
			log.Printf("read err: %v", err)
			continue
		}
		msg, err := message.Parse(buf[:n])
		if err != nil {
			log.Printf("ignored undecodable packet from %s: %v", raddr, err)
			continue
		}

		req, ok := msg.(*message.CreateSessionRequest)
		if !ok {
			log.Printf("ignored %s from %s", msg.MessageTypeName(), raddr)
			continue
		}

		sgwTeid := uint32(0)
		if req.SenderFTEIDC != nil {
			if v, err := req.SenderFTEIDC.TEID(); err == nil {
				sgwTeid = v
			}
		}
		if sgwTeid == 0 {
			log.Printf("CSR missing sender F-TEID; cannot respond to %s", raddr)
			continue
		}

		seq := req.Sequence()
		pgwCtrl := randNonZeroUint32(uint32(*pgwCtrlTEID))
		pgwU := randNonZeroUint32(uint32(*pgwUTeid))

		if *delay > 0 {
			log.Printf("[*] Got CSR seq=0x%x teid=0x%x from %s; delaying %s", seq, sgwTeid, raddr, *delay)
			time.Sleep(*delay)
		} else {
			log.Printf("[*] Got CSR seq=0x%x teid=0x%x from %s", seq, sgwTeid, raddr)
		}

		if err := sendCSRResponse(conn, raddr, sgwTeid, seq, pgwCtrl, pgwU, *paa, uint8(*ebi)); err != nil {
			log.Printf("send CSR response failed: %v", err)
			continue
