		ie.NewFullyQualifiedTEID(gtpv2.IFTypeS5S8PGWGTPU, pgwUTeid, localIP, ""),
	)

	rsp := message.NewCreateSessionResponse(
		sgwTeid, seq,
		cause,
		ctrlFTEID,
		pa,
		bctx,
	)

	b, err := rsp.Marshal()
	if err != nil {
		return fmt.Errorf("marshal CSR response: %w", err)
	}
	if _, err := conn.WriteToUDP(b, raddr); err != nil {
		return fmt.Errorf("send CSR response: %w", err)
	}
	log.Printf("[+] Sent CreateSessionResponse seq=0x%x teid=0x%x -> %s (ctrl=0x%x u=0x%x)", seq, sgwTeid, raddr, pgwCtrlTeid, pgwUTeid)
	return nil
}

