// Build BearerResourceCommand manually (message type 68)
// GTPv2-C header + IEs: Linked EBI, PTI, TAD (Traffic Aggregate Description)
func buildBearerResourceCommand(teid, seq uint32) []byte {
	// IEs
	// Linked EPS Bearer ID (IE Type 73)
	linkedEbiIE := []byte{
		0x49,       // IE Type: EPS Bearer ID (73)
		0x00, 0x01, // Length: 1
		0x00, // Spare + Instance
		0x05, // EBI = 5
	}

	// Procedure Transaction ID (IE Type 100)
	ptiIE := []byte{
		0x64,       // IE Type: PTI (100)
		0x00, 0x01, // Length: 1
		0x00, // Spare + Instance
		0x01, // PTI = 1
	}

	// Traffic Aggregate Description (IE Type 85)
	// Simple TFT: Create new TFT with 1 packet filter
	tad := []byte{
		0x31,       // TFT operation: Create new (0x20) | E bit (0x10) | 1 filter
		0x10,       // Packet filter ID 0, direction pre-Rel7
		0x02,       // Filter length
		0x70, 0x00, // Match all (protocol ID any)
	}
	tadIE := make([]byte, 4+len(tad))
	tadIE[0] = 0x55 // IE Type: TAD (85)
	binary.BigEndian.PutUint16(tadIE[1:3], uint16(len(tad)))
	tadIE[3] = 0x00 // Spare + Instance
	copy(tadIE[4:], tad)

	// Combine all IEs
	payload := append(linkedEbiIE, ptiIE...)
	payload = append(payload, tadIE...)

	// Build GTPv2-C header
	// Version=2, P=0, T=1 (TEID present), Spare=0
	header := make([]byte, 12)
	header[0] = 0x48 // Version 2, T=1
	header[1] = MsgTypeBearerResourceCommand
	binary.BigEndian.PutUint16(header[2:4], uint16(len(payload)+8)) // Length (includes TEID + Seq)
	binary.BigEndian.PutUint32(header[4:8], teid)
	header[8] = byte(seq >> 16)
	header[9] = byte(seq >> 8)
	header[10] = byte(seq)
	header[11] = 0x00 // Spare

	return append(header, payload...)
}

// Build BearerResourceFailureIndication manually (message type 69)
func buildBearerResourceFailureIndication(teid, seq uint32) []byte {
	// IEs
	// Cause (IE Type 2) - No Resources Available
	causeIE := []byte{
		0x02,       // IE Type: Cause (2)
		0x00, 0x02, // Length: 2
		0x00, // Spare + Instance
		0x49, // Cause: No Resources Available (73)
		0x00, // Spare flags
	}

	// Linked EPS Bearer ID (IE Type 73)
	linkedEbiIE := []byte{
		0x49,       // IE Type: EPS Bearer ID (73)
		0x00, 0x01, // Length: 1
		0x00, // Spare + Instance
		0x05, // EBI = 5
	}

	// Procedure Transaction ID (IE Type 100)
	ptiIE := []byte{
		0x64,       // IE Type: PTI (100)
		0x00, 0x01, // Length: 1
		0x00, // Spare + Instance
		0x01, // PTI = 1
	}

	// Combine all IEs
	payload := append(causeIE, linkedEbiIE...)
	payload = append(payload, ptiIE...)

	// Build GTPv2-C header
	header := make([]byte, 12)
	header[0] = 0x48 // Version 2, T=1
	header[1] = MsgTypeBearerResourceFailureIndication
	binary.BigEndian.PutUint16(header[2:4], uint16(len(payload)+8))
	binary.BigEndian.PutUint32(header[4:8], teid)
	header[8] = byte(seq >> 16)
	header[9] = byte(seq >> 8)
	header[10] = byte(seq)
	header[11] = 0x00

	return append(header, payload...)
}

func modifyBearerResponse(teid, seq uint32) message.Message {
	return message.NewModifyBearerResponse(
		teid, seq,
		ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil),
		ie.NewBearerContext(
			ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil),
			ie.NewEPSBearerID(5),
		),
	)
}

func sendMsg(conn *net.UDPConn, addr *net.UDPAddr, msg message.Message) error {
	b := make([]byte, msg.MarshalLen())
	if err := msg.MarshalTo(b); err != nil {
		return err
	}
	_, err := conn.WriteToUDP(b, addr)
	return err
}

