func startMMEServer(conn *net.UDPConn, sgwS11TeidCh chan<- uint32, updateReqCh chan<- bearerReqInfo) {
	log.Printf("[MME] Listening on %s", conn.LocalAddr())

	buf := make([]byte, 4096)
	for {
		n, raddr, err := conn.ReadFromUDP(buf)
		if err != nil {
			log.Printf("[MME] read error: %v", err)
			continue
		}
		msg, err := message.Parse(buf[:n])
		if err != nil {
			log.Printf("[MME] parse error: %v", err)
			continue
		}

		switch m := msg.(type) {
		case *message.CreateSessionResponse:
			sgwTeid := uint32(0)
			if m.SenderFTEIDC != nil {
				if v, err := m.SenderFTEIDC.TEID(); err == nil {
					sgwTeid = v
				}
			}
			if sgwTeid != 0 {
				select {
				case sgwS11TeidCh <- sgwTeid:
				default:
				}
				log.Printf("[MME] CreateSessionResponse from %s, SGW S11 TEID=0x%x", raddr, sgwTeid)
			}
		case *message.UpdateBearerRequest:
			ebi := ebiFromBearerContexts(m.BearerContexts, 5)
			req := bearerReqInfo{seq: m.Sequence(), ebi: ebi}
			select {
			case updateReqCh <- req:
			default:
			}
			log.Printf("[MME] UpdateBearerRequest from %s seq=0x%x ebi=%d", raddr, req.seq, req.ebi)
		default:
			log.Printf("[MME] recv %s from %s", msg.MessageTypeName(), raddr)
		}
	}
}

func startPGWServer(conn *net.UDPConn, pgwIP, paa string, pgwCtrlTeid uint32, sgwS5cCh chan<- s5cInfo) {
	log.Printf("[PGW] Listening on %s", conn.LocalAddr())

	pgwUteid := randNonZeroUint32(0)
	var sgwTeid uint32

	buf := make([]byte, 4096)
	for {
		n, raddr, err := conn.ReadFromUDP(buf)
		if err != nil {
			log.Printf("[PGW] read error: %v", err)
			continue
		}
		msg, err := message.Parse(buf[:n])
		if err != nil {
			log.Printf("[PGW] parse error: %v", err)
			continue
		}

		switch m := msg.(type) {
		case *message.CreateSessionRequest:
			if m.SenderFTEIDC != nil {
				if v, err := m.SenderFTEIDC.TEID(); err == nil {
					sgwTeid = v
				}
			}
			ebi := ebiFromCreateSessionRequest(m, 5)
			select {
			case sgwS5cCh <- s5cInfo{sgwTeid: sgwTeid, ebi: ebi}:
			default:
			}

			resp := message.NewCreateSessionResponse(
				sgwTeid, m.Sequence(),
				ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil),
				ie.NewFullyQualifiedTEID(gtpv2.IFTypeS5S8PGWGTPC, pgwCtrlTeid, pgwIP, "").WithInstance(1),
				ie.NewPDNAddressAllocation(paa),
				ie.NewAPNRestriction(gtpv2.APNRestrictionNoExistingContextsorRestriction),
				ie.NewBearerContext(
					ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil),
					ie.NewEPSBearerID(ebi),
					ie.NewFullyQualifiedTEID(gtpv2.IFTypeS5S8PGWGTPU, pgwUteid, pgwIP, "").WithInstance(2),
					ie.NewBearerQoS(1, 9, 1, 1, 0, 0, 0, 0),
				),
			)
			if err := sendMsg(conn, raddr, resp); err != nil {
				log.Printf("[PGW] send CSRsp error: %v", err)
			} else {
				log.Printf("[PGW] CSRsp sent to %s (SGW TEID=0x%x, EBI=%d)", raddr, sgwTeid, ebi)
			}
		case *message.DeleteSessionRequest:
			teid := sgwTeid
			if teid == 0 && m.SenderFTEIDC != nil {
				if v, err := m.SenderFTEIDC.TEID(); err == nil {
					teid = v
				}
			}
			resp := message.NewDeleteSessionResponse(
				teid, m.Sequence(),
				ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil),
			)
			if err := sendMsg(conn, raddr, resp); err != nil {
				log.Printf("[PGW] send DSRsp error: %v", err)
			} else {
				log.Printf("[PGW] DSRsp sent to %s (SGW TEID=0x%x)", raddr, teid)
			}
		default:
			log.Printf("[PGW] recv %s from %s", msg.MessageTypeName(), raddr)
		}
	}
}

func sendCreateSessionRequest(conn *net.UDPConn, raddr *net.UDPAddr, imsi, apn, mcc, mnc, mmeIP, pgwIP string, mmeTeid, pgwTeid uint32, ebi uint8) error {
	senderFTEID := ie.NewFullyQualifiedTEID(gtpv2.IFTypeS11MMEGTPC, mmeTeid, mmeIP, "")
	pgwFTEID := ie.NewFullyQualifiedTEID(gtpv2.IFTypeS5S8PGWGTPC, pgwTeid, pgwIP, "").WithInstance(1)

	bearer := ie.NewBearerContext(
		ie.NewEPSBearerID(ebi),
		ie.NewBearerQoS(1, 9, 1, 1, 0, 0, 0, 0),
	)

	csr := message.NewCreateSessionRequest(
		0, randSeq(),
		ie.NewIMSI(imsi),
		ie.NewMSISDN("818000000001"),
		ie.NewMobileEquipmentIdentity("123456789012345"),
		ie.NewServingNetwork(mcc, mnc),
		ie.NewRATType(gtpv2.RATTypeEUTRAN),
		ie.NewIndicationFromOctets(0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00),
		senderFTEID,
		pgwFTEID,
		ie.NewAccessPointName(apn),
		ie.NewSelectionMode(gtpv2.SelectionModeMSorNetworkProvidedAPNSubscribedVerified),
		ie.NewPDNType(gtpv2.PDNTypeIPv4),
		ie.NewPDNAddressAllocation("0.0.0.0"),
		ie.NewAPNRestriction(gtpv2.APNRestrictionNoExistingContextsorRestriction),
		ie.NewAggregateMaximumBitRate(10000000, 10000000),
		bearer,
	)

	payload, err := csr.Marshal()
	if err != nil {
		return fmt.Errorf("marshal CSR: %w", err)
	}
	if _, err := conn.WriteToUDP(payload, raddr); err != nil {
		return fmt.Errorf("send CSR: %w", err)
	}
	return nil
}

func sendUpdateBearerRequest(conn *net.UDPConn, raddr *net.UDPAddr, sgwTeid uint32, ebi uint8) error {
	req := message.NewUpdateBearerRequest(
		sgwTeid, randSeq(),
		ie.NewBearerContext(ie.NewEPSBearerID(ebi)),
	)
	payload, err := req.Marshal()
	if err != nil {
		return fmt.Errorf("marshal UpdateBearerRequest: %w", err)
	}
	if _, err := conn.WriteToUDP(payload, raddr); err != nil {
		return fmt.Errorf("send UpdateBearerRequest: %w", err)
	}
	return nil
}

func sendDeleteSessionRequest(conn *net.UDPConn, raddr *net.UDPAddr, sgwTeid uint32, ebi uint8) error {
	req := message.NewDeleteSessionRequest(
		sgwTeid, randSeq(),
		ie.NewEPSBearerID(ebi),
	)
	payload, err := req.Marshal()
	if err != nil {
		return fmt.Errorf("marshal DeleteSessionRequest: %w", err)
	}
	if _, err := conn.WriteToUDP(payload, raddr); err != nil {
		return fmt.Errorf("send DeleteSessionRequest: %w", err)
	}
	return nil
}

func sendUpdateBearerResponse(conn *net.UDPConn, raddr *net.UDPAddr, sgwTeid, seq uint32, ebi uint8) error {
	resp := message.NewUpdateBearerResponse(
		sgwTeid, seq,
		ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil),
		ie.NewBearerContext(
			ie.NewEPSBearerID(ebi),
			ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil),
		),
	)
	payload, err := resp.Marshal()
	if err != nil {
		return fmt.Errorf("marshal UpdateBearerResponse: %w", err)
	}
	if _, err := conn.WriteToUDP(payload, raddr); err != nil {
		return fmt.Errorf("send UpdateBearerResponse: %w", err)
	}
	return nil
}

func sendMsg(conn *net.UDPConn, raddr *net.UDPAddr, msg message.Message) error {
	b, err := message.Marshal(msg)
	if err != nil {
		return fmt.Errorf("marshal %T: %w", msg, err)
	}
	if _, err := conn.WriteToUDP(b, raddr); err != nil {
		return fmt.Errorf("send %T: %w", msg, err)
	}
	return nil
}

func ebiFromCreateSessionRequest(req *message.CreateSessionRequest, fallback uint8) uint8 {
	if req.LinkedEBI != nil {
		if v, err := req.LinkedEBI.EPSBearerID(); err == nil && v != 0 {
			return v
		}
	}
	for _, bc := range req.BearerContextsToBeCreated {
		children, err := bc.BearerContext()
		if err != nil {
			continue
		}
		for _, child := range children {
			if child == nil || child.Type != ie.EPSBearerID {
				continue
			}
			if v, err := child.EPSBearerID(); err == nil && v != 0 {
				return v
			}
		}
	}
	return fallback
}

func ebiFromBearerContexts(bcs []*ie.IE, fallback uint8) uint8 {
	for _, bc := range bcs {
		if bc == nil {
			continue
		}
		children, err := bc.BearerContext()
		if err != nil {
			continue
		}
		for _, child := range children {
			if child == nil || child.Type != ie.EPSBearerID {
				continue
			}
			if v, err := child.EPSBearerID(); err == nil && v != 0 {
				return v
			}
		}
	}
	return fallback
}

func waitUint32(label string, ch <-chan uint32, timeout time.Duration) uint32 {
	select {
	case v := <-ch:
		return v
	case <-time.After(timeout):
		log.Fatalf("timeout waiting for %s", label)
	}
	return 0
}

func waitS5cInfo(ch <-chan s5cInfo, timeout time.Duration) s5cInfo {
	select {
	case v := <-ch:
		if v.sgwTeid == 0 {
			log.Fatalf("received invalid SGW S5C TEID")
		}
		return v
	case <-time.After(timeout):
		log.Fatalf("timeout waiting for S5C info")
	}
	return s5cInfo{}
}

func waitBearerReq(label string, ch <-chan bearerReqInfo, timeout time.Duration) bearerReqInfo {
	select {
	case v := <-ch:
		return v
	case <-time.After(timeout):
		log.Fatalf("timeout waiting for %s", label)
	}
	return bearerReqInfo{}
}

func hostFromAddr(addr string) (string, error) {
	host, _, err := net.SplitHostPort(addr)
	if err != nil {
		return "", err
	}
	if host == "" {
		host = "127.0.0.1"
	}
	if strings.HasPrefix(host, "[") && strings.HasSuffix(host, "]") {
		host = strings.TrimPrefix(strings.TrimSuffix(host, "]"), "[")
	}
	return host, nil
}

func listenUDP(addr, label string) *net.UDPConn {
	laddr, err := net.ResolveUDPAddr("udp", addr)
	if err != nil {
		log.Fatalf("[%s] resolve addr: %v", label, err)
	}
	conn, err := net.ListenUDP("udp", laddr)
	if err != nil {
		log.Fatalf("[%s] listen: %v", label, err)
	}
	return conn
}

func randSeq() uint32 {
	// Clear OGS_GTP_CMD_XACT_ID bit (0x800000) to avoid command-stage misclassification.
	seq := rand.Uint32() & 0x007fffff
	if seq == 0 {
		seq = 1
	}
	return seq
}

func randNonZeroUint32(v uint32) uint32 {
	if v != 0 {
		return v
	}
	r := rand.Uint32()
	if r == 0 {
		return 1
	}
	return r
}

