func ebiFromCreateSessionRequest(req *message.CreateSessionRequest, fallback uint8) uint8 {
	if req.LinkedEBI != nil {
		if v, err := req.LinkedEBI.EPSBearerID(); err == nil && v != 0 {
			return v
		}
	}
	for _, bc := range req.BearerContextsToBeCreated {
		children, err := bc.BearerContext()
		if err != nil {
			continue
		}
		for _, child := range children {
			if child == nil || child.Type != ie.EPSBearerID {
				continue
			}
			if v, err := child.EPSBearerID(); err == nil && v != 0 {
				return v
			}
		}
	}
	return fallback
}

func ebiFromDeleteBearerRequest(req *message.DeleteBearerRequest, fallback uint8) uint8 {
	if req.LinkedEBI != nil {
		if v, err := req.LinkedEBI.EPSBearerID(); err == nil && v != 0 {
			return v
		}
	}
	for _, e := range req.EBIs {
		if v, err := e.EPSBearerID(); err == nil && v != 0 {
			return v
		}
	}
	if req.FailedBearerContext != nil {
		children, err := req.FailedBearerContext.BearerContext()
		if err == nil {
			for _, child := range children {
				if child == nil || child.Type != ie.EPSBearerID {
					continue
				}
				if v, err := child.EPSBearerID(); err == nil && v != 0 {
					return v
				}
			}
		}
	}
	return fallback
}

func ebiFromBearerContexts(bcs []*ie.IE, fallback uint8) uint8 {
	for _, bc := range bcs {
		if bc == nil {
			continue
		}
		children, err := bc.BearerContext()
		if err != nil {
			continue
		}
		for _, child := range children {
			if child == nil || child.Type != ie.EPSBearerID {
