type sessionInfo struct {
	sgwTeid uint32
	mmeTeid uint32
	ebi     uint8
	localIP string
}

type uPlaneInfo struct {
	ip   string
	teid uint32
}

func dialGTPv2(target string, port int, laddr string) (*net.UDPConn, string) {
	var lp *net.UDPAddr
	if laddr != "" {
		var err error
		lp, err = net.ResolveUDPAddr("udp", net.JoinHostPort(laddr, "0"))
		if err != nil {
			log.Fatalf("resolve laddr: %v", err)
		}
	}

	rp, err := net.ResolveUDPAddr("udp", net.JoinHostPort(target, fmt.Sprintf("%d", port)))
	if err != nil {
		log.Fatalf("resolve raddr: %v", err)
	}

	conn, err := net.DialUDP("udp", lp, rp)
	if err != nil {
		log.Fatalf("dial udp: %v", err)
	}

	localIP := ""
	if udpAddr, ok := conn.LocalAddr().(*net.UDPAddr); ok && udpAddr.IP != nil {
		localIP = udpAddr.IP.String()
	}
	if localIP == "" {
		log.Fatal("local IP unknown (set --laddr)")
	}
	log.Printf("[*] Target %s (local %s)", rp, localIP)
	return conn, localIP
}

func initBaseSeq(v uint32) uint32 {
	if v != 0 {
		return v
	}
	seq := rand.Uint32() & 0x00ffffff
	if seq == 0 {
		seq = 1
	}
	return seq
}

func nextSeq(v uint32) uint32 {
	v++
	if v == 0 || v > 0x00ffffff {
		return 1
	}
	return v
}

func randNonZeroUint32(v uint32) uint32 {
	if v != 0 {
		return v
	}
	r := rand.Uint32()
	if r == 0 {
		return 1
	}
	return r
}

func buildCSR(seq uint32, imsi, apn, localIP, pgwIP, mcc, mnc string, mmeTEID, pgwTEID, enbTEID uint32, enbIP string) (*gtpv2msg.CreateSessionRequest, error) {
	if localIP == "" || pgwIP == "" || enbIP == "" {
		return nil, fmt.Errorf("missing local, PGW, or eNB IP")
	}

	senderFTEID := ie.NewFullyQualifiedTEID(gtpv2.IFTypeS11MMEGTPC, mmeTEID, localIP, "")
	pgwFTEID := ie.NewFullyQualifiedTEID(gtpv2.IFTypeS5S8PGWGTPC, pgwTEID, pgwIP, "").WithInstance(1)
	enbFTEID := ie.NewFullyQualifiedTEID(gtpv2.IFTypeS1UeNodeBGTPU, enbTEID, enbIP, "")

	bearer := ie.NewBearerContext(
		ie.NewEPSBearerID(5),
		enbFTEID,
		ie.NewBearerQoS(1, 2, 1, 9, 50000, 50000, 50000, 50000),
	)

	return gtpv2msg.NewCreateSessionRequest(
		0, seq,
		ie.NewIMSI(imsi),
		ie.NewMSISDN("0000000000"),
		ie.NewMobileEquipmentIdentity("353490061234560"),
		ie.NewServingNetwork(mcc, mnc),
		ie.NewRATType(gtpv2.RATTypeEUTRAN),
		ie.NewPDNType(gtpv2.PDNTypeIPv4),
		ie.NewSelectionMode(gtpv2.SelectionModeMSorNetworkProvidedAPNSubscribedVerified),
		ie.NewAccessPointName(apn),
		ie.NewAggregateMaximumBitRate(500000, 500000),
		senderFTEID,
		pgwFTEID,
		bearer,
	), nil
}

func waitCSRResponse(conn *net.UDPConn, timeout time.Duration) (uint32, uint8, error) {
	buf := make([]byte, 2048)
	_ = conn.SetReadDeadline(time.Now().Add(timeout))
	n, err := conn.Read(buf)
	_ = conn.SetReadDeadline(time.Time{})
	if err != nil {
		return 0, 0, fmt.Errorf("read CSR response: %w", err)
	}

	msg, err := gtpv2msg.Parse(buf[:n])
	if err != nil {
		return 0, 0, fmt.Errorf("parse CSR response: %w", err)
	}
	res, ok := msg.(*gtpv2msg.CreateSessionResponse)
	if !ok {
		return 0, 0, fmt.Errorf("unexpected message type %T", msg)
	}
	if res.Cause == nil {
		return 0, 0, fmt.Errorf("no Cause IE in response")
	}
	cause, err := res.Cause.Cause()
	if err != nil {
		return 0, 0, fmt.Errorf("parse Cause: %w", err)
	}
	if cause != gtpv2.CauseRequestAccepted && cause != gtpv2.CauseRequestAcceptedPartially {
		return 0, 0, fmt.Errorf("CSR rejected: cause=%d", cause)
	}
	if res.SenderFTEIDC == nil {
		return 0, 0, fmt.Errorf("no SGW S11 F-TEID in response")
	}
	sgwTeid, err := res.SenderFTEIDC.TEID()
	if err != nil {
		return 0, 0, fmt.Errorf("parse SGW TEID: %w", err)
	}

	ebi := uint8(0)
	if res.EBI != nil {
		if v, err := res.EBI.EPSBearerID(); err == nil {
			ebi = v
		}
	}
	if ebi == 0 {
		for _, b := range res.BearerContextsCreated {
			if v, err := b.EPSBearerID(); err == nil {
				ebi = v
				break
			}
		}
	}
	if ebi == 0 {
		ebi = 5
	}
	return sgwTeid, ebi, nil
}

func sendMessage(conn *net.UDPConn, msg gtpv2msg.Message) error {
	b, err := gtpv2msg.Marshal(msg)
	if err != nil {
		return fmt.Errorf("marshal %s: %w", msg.MessageTypeName(), err)
	}
	if _, err := conn.Write(b); err != nil {
		return fmt.Errorf("send %s: %w", msg.MessageTypeName(), err)
	}
	return nil
}

func sendRABRequest(conn *net.UDPConn, sess sessionInfo, seq uint32) error {
	req := gtpv2msg.NewReleaseAccessBearersRequest(
		sess.sgwTeid, seq,
		ie.NewEPSBearerID(sess.ebi),
	)
	return sendMessage(conn, req)
}

func waitForDDN(conn *net.UDPConn, timeout time.Duration) (uint32, uint8, error) {
	buf := make([]byte, 4096)
	deadline := time.Now().Add(timeout)
	for {
		if time.Now().After(deadline) {
			return 0, 0, fmt.Errorf("timeout waiting for DDN")
		}
		_ = conn.SetReadDeadline(deadline)
		n, err := conn.Read(buf)
		if err != nil {
			return 0, 0, fmt.Errorf("read: %w", err)
		}
		msg, err := gtpv2msg.Parse(buf[:n])
		if err != nil {
			log.Printf("[!] parse error: %v", err)
			continue
		}
		if ddn, ok := msg.(*gtpv2msg.DownlinkDataNotification); ok {
			ebi := uint8(0)
			if ddn.EPSBearerID != nil {
				if v, err := ddn.EPSBearerID.EPSBearerID(); err == nil {
					ebi = v
				}
			}
			return ddn.Sequence(), ebi, nil
		}
		log.Printf("[*] Ignored message type=%d (%s)", msg.MessageType(), msg.MessageTypeName())
	}
}

func waitForDSR(conn *net.UDPConn, timeout time.Duration) error {
	buf := make([]byte, 4096)
	deadline := time.Now().Add(timeout)
	for {
		if time.Now().After(deadline) {
			return fmt.Errorf("timeout waiting for DeleteSessionResponse")
		}
		_ = conn.SetReadDeadline(deadline)
		n, err := conn.Read(buf)
		if err != nil {
			return fmt.Errorf("read: %w", err)
		}
		msg, err := gtpv2msg.Parse(buf[:n])
		if err != nil {
			log.Printf("[!] parse error: %v", err)
			continue
		}
		if dsr, ok := msg.(*gtpv2msg.DeleteSessionResponse); ok {
			cause := uint8(0)
			if dsr.Cause != nil {
				if v, err := dsr.Cause.Cause(); err == nil {
					cause = v
				}
			}
			log.Printf("[+] Received DeleteSessionResponse seq=0x%x cause=%d", dsr.Sequence(), cause)
			return nil
		}
		log.Printf("[*] Ignored message type=%d (%s) while waiting for DSR", msg.MessageType(), msg.MessageTypeName())
	}
}

func sendDeleteSessionRequest(conn *net.UDPConn, sess sessionInfo, seq uint32) error {
	req := gtpv2msg.NewDeleteSessionRequest(
		sess.sgwTeid, seq,
		ie.NewEPSBearerID(sess.ebi),
		ie.NewFullyQualifiedTEID(gtpv2.IFTypeS11MMEGTPC, sess.mmeTeid, sess.localIP, ""),
	)
	return sendMessage(conn, req)
}

func sendDDNAck(conn *net.UDPConn, sgwTeid, ddnSeq uint32) error {
	ack := gtpv2msg.NewDownlinkDataNotificationAcknowledge(
		sgwTeid, ddnSeq,
		ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil),
	)
	return sendMessage(conn, ack)
}

func sendGTPU(addr string, port int, teid uint32) error {
	payload := []byte{0xde, 0xad, 0xbe, 0xef}
	tpdu := gtpv1msg.NewTPDU(teid, payload)
	b, err := tpdu.Marshal()
	if err != nil {
		return fmt.Errorf("marshal TPDU: %w", err)
	}

	rp, err := net.ResolveUDPAddr("udp", net.JoinHostPort(addr, fmt.Sprintf("%d", port)))
	if err != nil {
		return fmt.Errorf("resolve GTP-U addr: %w", err)
	}
	conn, err := net.DialUDP("udp", nil, rp)
	if err != nil {
		return fmt.Errorf("dial GTP-U: %w", err)
	}
	defer conn.Close()
	if _, err := conn.Write(b); err != nil {
		return fmt.Errorf("send GTP-U: %w", err)
	}
	return nil
}

func readUPlaneInfo(path string, wait time.Duration) (string, uint32, error) {
	deadline := time.Now().Add(wait)
	for {
		ip, teid, err := readUPlaneInfoOnce(path)
		if err == nil {
			return ip, teid, nil
		}
		if time.Now().After(deadline) {
			return "", 0, err
		}
		time.Sleep(200 * time.Millisecond)
	}
}

func waitUPlaneInfo(ch <-chan uPlaneInfo, timeout time.Duration) (string, uint32, error) {
	select {
	case info := <-ch:
		if info.teid == 0 {
			return info.ip, 0, fmt.Errorf("received empty TEID")
		}
		return info.ip, info.teid, nil
	case <-time.After(timeout):
		return "", 0, fmt.Errorf("timeout waiting for PGW u-plane info")
	}
}

func readUPlaneInfoOnce(path string) (string, uint32, error) {
	b, err := os.ReadFile(path)
	if err != nil {
		return "", 0, err
	}

	var ip string
	var teid uint32
	tokens := strings.Fields(string(b))
	for _, t := range tokens {
		if strings.HasPrefix(t, "ip=") {
			ip = strings.TrimPrefix(t, "ip=")
			continue
		}
		if strings.HasPrefix(t, "teid=") {
			val := strings.TrimPrefix(t, "teid=")
			parsed, err := strconv.ParseUint(val, 0, 32)
			if err != nil {
				return "", 0, fmt.Errorf("invalid teid %q: %w", val, err)
			}
			teid = uint32(parsed)
			continue
		}
		if teid == 0 {
			if parsed, err := strconv.ParseUint(t, 0, 32); err == nil {
				teid = uint32(parsed)
			}
		}
	}

	if teid == 0 {
		return ip, 0, fmt.Errorf("no teid in file")
	}
	return ip, teid, nil
}

func startPGWMock(bind, paa string, defEBI uint8, ctrlTeid, upTeid uint32, ignoreMBR bool, dumpSGWS5U, pgwIP string, uplaneCh chan<- uPlaneInfo) (*net.UDPConn, error) {
	laddr, err := net.ResolveUDPAddr("udp", bind)
	if err != nil {
		return nil, fmt.Errorf("resolve bind: %w", err)
	}

	conn, err := net.ListenUDP("udp", laddr)
	if err != nil {
		return nil, fmt.Errorf("listen udp: %w", err)
	}
	log.Printf("[*] PGW-C mock listening on %s", conn.LocalAddr())

	pgwCtrlTeid := randNonZeroUint32(ctrlTeid)
	pgwUpTeid := randNonZeroUint32(upTeid)
	var sgwS5cTeid uint32

	go func() {
		buf := make([]byte, 4096)
		for {
			n, raddr, err := conn.ReadFromUDP(buf)
			if err != nil {
				return
			}
			go pgwHandlePacket(conn, raddr, buf[:n], pgwCtrlTeid, pgwUpTeid, defEBI, paa, ignoreMBR, dumpSGWS5U, pgwIP, uplaneCh, &sgwS5cTeid)
		}
	}()

	return conn, nil
}

func pgwHandlePacket(conn *net.UDPConn, raddr *net.UDPAddr, b []byte, pgwCtrlTeid, pgwUpTeid uint32, defEBI uint8, paa string, ignoreMBR bool, dumpSGWS5U, pgwIP string, uplaneCh chan<- uPlaneInfo, sgwS5cTeid *uint32) {
	msg, err := gtpv2msg.Parse(b)
	if err != nil {
		log.Printf("parse msg from %s: %v", raddr, err)
		return
	}

	switch m := msg.(type) {
	case *gtpv2msg.CreateSessionRequest:
		if err := pgwHandleCSR(conn, raddr, m, pgwCtrlTeid, pgwUpTeid, defEBI, paa, dumpSGWS5U, pgwIP, uplaneCh, sgwS5cTeid); err != nil {
			log.Printf("handle CSR: %v", err)
		}
	case *gtpv2msg.DeleteSessionRequest:
		teid := atomic.LoadUint32(sgwS5cTeid)
		if teid == 0 && m.SenderFTEIDC != nil {
			if v, err := m.SenderFTEIDC.TEID(); err == nil {
				teid = v
			}
		}
		if teid == 0 {
			teid = m.TEID()
			log.Printf("[!] SGW S5C TEID unknown, falling back to request TEID=0x%x", teid)
		}
		resp := gtpv2msg.NewDeleteSessionResponse(teid, m.Sequence(),
			ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil),
		)
		if err := pgwSendMsg(conn, raddr, resp); err != nil {
			log.Printf("send DSRsp: %v", err)
		} else {
			log.Printf("[+] DSRsp sent to %s (SGW TEID=0x%x)", raddr, teid)
		}
	case *gtpv2msg.ModifyBearerRequest:
		if ignoreMBR {
			log.Printf("[*] Ignoring ModifyBearerRequest from %s seq=0x%x", raddr, m.Sequence())
			return
		}
		resp := gtpv2msg.NewModifyBearerResponse(m.TEID(), m.Sequence(),
			ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil),
		)
		pgwSendMsg(conn, raddr, resp)
	default:
		log.Printf("ignore msg type=%d from %s", msg.MessageType(), raddr)
	}
}

func pgwHandleCSR(conn *net.UDPConn, raddr *net.UDPAddr, req *gtpv2msg.CreateSessionRequest, pgwCtrlTeid, pgwUpTeid uint32, defEBI uint8, paa, dumpSGWS5U, pgwIP string, uplaneCh chan<- uPlaneInfo, sgwS5cTeid *uint32) error {
	sgwCtrlTEID := req.TEID()
	if req.SenderFTEIDC != nil {
		if v, err := req.SenderFTEIDC.TEID(); err == nil {
			sgwCtrlTEID = v
		}
	}
	if sgwCtrlTEID != 0 {
		atomic.StoreUint32(sgwS5cTeid, sgwCtrlTEID)
	}

	ebi := findEBIFromCSR(req, defEBI)
	captureSGWS5UInfo(req, dumpSGWS5U, uplaneCh)

	fteidIP := pgwIP
	if fteidIP == "" {
		fteidIP = localIPv4(conn)
	}

	resp := gtpv2msg.NewCreateSessionResponse(
		sgwCtrlTEID, req.Sequence(),
		ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil),
		ie.NewFullyQualifiedTEID(gtpv2.IFTypeS5S8PGWGTPC, pgwCtrlTeid, fteidIP, "").WithInstance(1),
		ie.NewPDNAddressAllocation(paa),
		ie.NewBearerContext(
			ie.NewCause(gtpv2.CauseRequestAccepted, 0, 0, 0, nil),
			ie.NewEPSBearerID(ebi),
			ie.NewFullyQualifiedTEID(gtpv2.IFTypeS5S8PGWGTPU, pgwUpTeid, fteidIP, "").WithInstance(2),
		),
	)

	log.Printf("[+] CSR from %s seq=0x%x ebi=%d -> respond TEID=0x%x PAA=%s PGW-C-TEID=0x%x PGW-U-TEID=0x%x",
		raddr, req.Sequence(), ebi, sgwCtrlTEID, paa, pgwCtrlTeid, pgwUpTeid)
	return pgwSendMsg(conn, raddr, resp)
}

func pgwSendMsg(conn *net.UDPConn, raddr *net.UDPAddr, msg gtpv2msg.Message) error {
	b, err := gtpv2msg.Marshal(msg)
	if err != nil {
		return fmt.Errorf("marshal %T: %w", msg, err)
	}
	if _, err := conn.WriteToUDP(b, raddr); err != nil {
		return fmt.Errorf("write %T: %w", msg, err)
	}
	return nil
}

func findEBIFromCSR(req *gtpv2msg.CreateSessionRequest, def uint8) uint8 {
	if req.LinkedEBI != nil {
		if v, err := req.LinkedEBI.EPSBearerID(); err == nil && v != 0 {
			return v
		}
	}
	for _, bc := range req.BearerContextsToBeCreated {
		children, err := bc.BearerContext()
		if err != nil {
			continue
		}
		for _, child := range children {
			if child == nil || child.Type != ie.EPSBearerID {
				continue
			}
			if v, err := child.EPSBearerID(); err == nil && v != 0 {
				return v
			}
		}
	}
	return def
}

func localIPv4(conn *net.UDPConn) string {
	if addr, ok := conn.LocalAddr().(*net.UDPAddr); ok {
		if ip := addr.IP.To4(); ip != nil {
			return ip.String()
		}
	}
	return ""
}

func captureSGWS5UInfo(req *gtpv2msg.CreateSessionRequest, path string, ch chan<- uPlaneInfo) {
	if path == "" && ch == nil {
		return
	}
	fteid, err := findSGWS5UFTEID(req)
	if err != nil {
		log.Printf("[!] SGW S5U F-TEID not found in CSR: %v", err)
		return
	}
	ip := ""
	if fteid.IPv4Address != nil {
		ip = fteid.IPv4Address.String()
	}
	info := uPlaneInfo{ip: ip, teid: fteid.TEIDGREKey}
	if ch != nil {
		select {
		case ch <- info:
		default:
		}
	}
	log.Printf("[+] SGW S5U TEID=0x%x IP=%s", info.teid, info.ip)
	if path == "" {
		return
	}
	content := fmt.Sprintf("teid=0x%x\n", info.teid)
	if info.ip != "" {
		content += fmt.Sprintf("ip=%s\n", info.ip)
	}
	if err := os.WriteFile(path, []byte(content), 0644); err != nil {
		log.Printf("[!] write %s failed: %v", path, err)
	}
}

func findSGWS5UFTEID(req *gtpv2msg.CreateSessionRequest) (*ie.FullyQualifiedTEIDFields, error) {
	for _, bc := range req.BearerContextsToBeCreated {
		if bc == nil {
			continue
		}
		ies, err := bc.BearerContext()
		if err != nil {
			continue
		}
		for _, child := range ies {
			if child == nil || child.Type != ie.FullyQualifiedTEID {
				continue
			}
			f, err := child.FullyQualifiedTEID()
			if err != nil {
				continue
			}
			if f.InterfaceType == gtpv2.IFTypeS5S8SGWGTPU {
				return f, nil
			}
		}
	}
	return nil, fmt.Errorf("SGW S5U F-TEID not present")
}

func hostFromAddrMaybe(addr string) string {
	host, _, err := net.SplitHostPort(addr)
	if err != nil {
		return ""
	}
	if host == "" || host == "0.0.0.0" || host == "::" {
		return ""
	}
	if strings.HasPrefix(host, "[") && strings.HasSuffix(host, "]") {
		host = strings.TrimPrefix(strings.TrimSuffix(host, "]"), "[")
	}
	return host
}
